package app.studyhub.api; import app.studyhub.infrastructure.UserRepository; import app.studyhub.security.JwtService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/auth") public class AuthController { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthController(UserRepository users,PasswordEncoder encoder,JwtService jwt){this.users=users;this.encoder=encoder;this.jwt=jwt;} @PostMapping("/login") public TokenResponse login(@Valid @RequestBody LoginRequest request){var user=users.findByEmail(request.email()).filter(u->encoder.matches(request.password(),u.getPasswordHash())).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Credenciales inválidas"));return new TokenResponse(jwt.issue(user.getEmail()),"Bearer");} @PostMapping("/forgot-password") @ResponseStatus(HttpStatus.ACCEPTED) public void forgot(){/* Integrar proveedor de correo en producción. */} }
